def cvss_severity(score):
    if score == 0.0:
        return "None"
    if score <= 3.9:
        return "Low"
    if score <= 6.9:
        return "Medium"
    if score <= 8.9:
        return "High"
    return "Critical"


inventory = [
    ("nginx", "1.18.0", 7.5),
    ("openssl", "1.0.1", 9.8),
    ("openssh", "9.6", 0.0),
]

for component, version, score in sorted(inventory, key=lambda item: item[2], reverse=True):
    print(f"{component} {version}: CVSS={score} severidad={cvss_severity(score)}")
